using System.Text.Json;
using System.Buffers.Binary;
using Stardust.Core.Assets;
using Stardust.Core.Protocol;
using Stardust.Core.Session;
namespace Stardust.Core.SmokeTests;
public static class SceneWorldCreatureView4FullScenarios
{
 static int checks;static void Check(bool v,string why){checks++;if(!v)throw new Exception(why);}
 static void Reject(Action a){try{a();}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){checks++;return;}throw new Exception("Expected rejection");}
 static readonly string path="object/synthetic_round43.iff",pin=new('0',64);static readonly uint crc=LegacyAssetPath.Checksum(path);
 static ObjectTemplateCatalog Catalog()=>new(new[]{new ObjectTemplateCatalogEntry(crc,path,pin,pin,SceneObjectResourceRecipe.CreatureDetail0)});
 static readonly LogicalAnimationClipSelection idle=new("appearance/lat/synthetic.lat","synthetic_idle",pin);
 static readonly IReadOnlyDictionary<string,LogicalAnimationClipSelection> movement=new Dictionary<string,LogicalAnimationClipSelection>{{"walk",idle},{"run",idle}};
 static CreatureView4Limits BL=>new(1048576,4096,65536,196608,1048576,4194304,16777216,16777216);
 static CreatureView4FullLimits DL=>new(1048576,4096,65536,1048576,1048576,4194304,16777216,16777216);
 static SceneWorldCreatureView4FullPolicy Policy()=>new(BL,DL,new(new(4096,65536,196608,1048576,4194304,16777216,262144,33554432,16777216),DL),new(MaximumStateBytes:134217728,MaximumOutputBytes:268435456,MaximumPendingEvents:262144,MaximumEventsPerApply:262144,MaximumWork:16777216));
 static SceneWorldCoordinator World(SceneWorldCreatureView4FullPolicy? policy=null,bool enabled=true,SceneWorldCreatureView6FullPolicy? full6=null)=>new(Catalog(),new Dictionary<SceneObjectResourceRecipe,SceneObjectResourceOptions>{{SceneObjectResourceRecipe.CreatureDetail0,new SceneCreatureResourceOptions(idle,movement,false)}},(_,_)=>throw new Exception("No synthetic loads"),SceneCreateZeroQuaternionPolicy.Reject,8,2,32,4194304,32,4194304,1048576,creatureView4FullPolicy:enabled?(policy??Policy()):null,creatureView6FullPolicy:full6);
 static byte[] Start(ulong id){using var s=new MemoryStream();using var w=new BinaryWriter(s);w.Write((ushort)9);w.Write(ZoneSceneProtocolCodec.CmdStartSceneOpcode);w.Write((byte)0);w.Write(id);w.Write((ushort)0);w.Write(0f);w.Write(0f);w.Write(0f);w.Write((ushort)0);w.Write(0UL);return s.ToArray();}
 static byte[] Create(ulong id)=>SceneObjectLifecycleCodec.EncodeCreate(new(id,0,0,0,1,0,0,0,crc,0));
 static long Stage(SceneWorldCoordinator w,ulong id,byte[]? baseline,byte[]? b6=null){long g=w.BeginSelection(id).Generation;Check(w.Accept(g,Start(id)),"start");Check(w.Accept(g,Create(id)),"create");if(baseline is not null)Check(w.Accept(g,baseline),"baseline");if(b6 is not null)Check(w.Accept(g,b6),"baseline6");Check(w.Accept(g,SceneObjectLifecycleCodec.EncodeEndBaselines(new(id))),"end");Check(w.CompleteMinimumSceneBarrier(g,true)is not null,"barrier");return g;}
 static object Text(ReplicationByteString s)=>new{Hex=Convert.ToHexString(s.CopyBytes()),Extended=s.UsesExtendedLength};
 static object Model(CreatureView4Baseline m)=>new{m.ObjectId,m.DeclaredCount,FloatBits=m.FloatBits.ToArray(),m.ListenTo,Encumbrances=new{m.Encumbrances.Counter,Values=m.Encumbrances.Values.ToArray()},SkillMods=new{m.SkillMods.Counter,Values=m.SkillMods.Values.Select(e=>new{e.RawCommand,Name=Text(e.Name),e.BaseValue,e.Bonus}).ToArray()},SpaceMissionObjects=new{m.SpaceMissionObjects.Counter,Values=m.SpaceMissionObjects.Values.ToArray()}};
 static object Row(CreatureView4FullState s)=>new{Model=Model(s.Model),s.Revision,s.DecodedBytes};
 static object Event(CreatureView4FullEvent e)=>new{e.Kind,e.Field,e.UpdateOrdinal,e.Opcode,e.Index,e.OldBits,e.NewBits,e.OldValue,e.NewValue,Name=e.Name is null?null:Text(e.Name),e.OldBase,e.OldBonus,e.NewBase,e.NewBonus,e.Pair,e.LogicalBytes};
 public static void Run(string fixture,string output)
 {
  using var doc=JsonDocument.Parse(File.ReadAllBytes(fixture));var records=new List<object>();int ordinal=0;
  foreach(var c in doc.RootElement.GetProperty("Cases").EnumerateArray())
  {
   var baseline=Convert.FromHexString(c.GetProperty("Baseline").GetString()!);var wire=Convert.FromHexString(c.GetProperty("Hex").GetString()!);var plan=CreatureView4FullCodec.Decode(wire,DL);ulong id=plan.ObjectId;using var w=World();long g=Stage(w,id,baseline);var before=w.FindCreatureView4Full(g,id)!;Check(w.IsCurrent(before)&&w.Snapshots()[0].CreatureView4Full?.Revision==before.Revision,"snapshot/full4");object initial=Row(before.State);
   if(ordinal%3==0)Check(w.Accept(g,wire),"raw");else if(ordinal%3==1)Check(w.ApplyCreatureView4FullDelta(g,before,plan),"direct");else{using var router=new SceneWorldCreatureView4FullApplicationRouter(w,maximumPayloadBytes:1048576);Check(router.Accept(g,wire),"router");}
   var current=w.FindCreatureView4Full(g,id)!;var batch=w.DrainCreatureView4FullEvents(g)!;Check(!w.IsCurrent(before)&&w.IsCurrent(current)&&!w.ApplyCreatureView4FullDelta(g,before,plan),"exact expected");Check(batch.Events.All(e=>e.StoreRevision==2),"source publication");for(int i=0;i<batch.Events.Count;i++)Check(w.IsCurrentCreatureView4FullEvent(batch,i),"delivery");long retained=w.RetainedCreatureView4FullBytes;var es=batch.Events.Select(e=>Event(e.Event)).ToArray();Check(w.AcknowledgeCreatureView4FullEvents(batch)&&!w.AcknowledgeCreatureView4FullEvents(batch),"ack epoch");long after=w.RetainedCreatureView4FullBytes;
   records.Add(new{Name=c.GetProperty("Name").GetString(),Initial=initial,Current=Row(current.State),Events=es,Retained=retained,AfterAck=after,StoreRevision=current.Revision,OpaqueCount=w.Snapshots()[0].Envelopes.Count});ordinal++;
  }
  var first=doc.RootElement.GetProperty("Cases")[0];var bw=Convert.FromHexString(first.GetProperty("Baseline").GetString()!);var dw=Convert.FromHexString(first.GetProperty("Hex").GetString()!);ulong actor=BinaryPrimitives.ReadUInt64LittleEndian(bw.AsSpan(6));var dp=CreatureView4FullCodec.Decode(dw,DL);
  using(var w=World()){long g=Stage(w,actor,null);Check(w.Snapshots()[0].Object.Phase==SceneObjectPhase.Finalized&&w.FindCreatureView4Full(g,actor)is null,"optional unseeded end");Reject(()=>w.Accept(g,dw));Check(w.Snapshots().Count==1,"typed failure retains unseeded target");Check(w.Accept(g,bw),"late private seed");Check(w.Accept(g,dw),"seeded update");w.Accept(g,Create(actor+1));w.Accept(g,SceneObjectLifecycleCodec.EncodeEndBaselines(new(actor+1)));Check(w.FindCreatureView4Full(g,actor+1)is null,"nonowner unseeded creature finalized");}
  using(var w=World(enabled:false)){long g=Stage(w,actor,bw);Check(!w.CreatureView4FullEnabled&&w.Snapshots()[0].Envelopes.Count==1,"default opaque");}
  using(var w=World()){long g=Stage(w,actor,bw);var s=w.FindCreatureView4Full(g,actor)!;var changes=w.DrainChanges(g)!;var bad=dw[..^1];Reject(()=>w.Accept(g,bad));Check(w.IsCurrent(s)&&w.IsCurrent(changes),"late wire retains world");Check(!w.ApplyCreatureView4FullDelta(g-1,s,dp),"stale generation");using var other=World();long og=Stage(other,actor,bw);Check(!w.ApplyCreatureView4FullDelta(g,other.FindCreatureView4Full(og,actor)!,dp),"foreign receipt");}
  using(var w=World()){long g=Stage(w,actor,bw);Check(w.Accept(g,dw),"history update");var b=w.DrainCreatureView4FullEvents(g)!;long journal=b.Events.Sum(e=>e.Event.LogicalBytes);w.Accept(g,SceneObjectLifecycleCodec.EncodeDestroy(new(actor,0)));Check(w.FindCreatureView4Full(g,actor)is null&&w.RetainedCreatureView4FullBytes==journal,"retire variable journal");Check(!w.IsCurrentCreatureView4FullEvent(b,0),"retire epoch");w.Accept(g,Create(actor));w.Accept(g,SceneObjectLifecycleCodec.EncodeEndBaselines(new(actor)));w.Accept(g,bw);var fresh=w.FindCreatureView4Full(g,actor)!;Check(fresh.State.Revision==1,"new incarnation state");var history=w.DrainCreatureView4FullEvents(g)!;Check(!w.IsCurrentCreatureView4FullEvent(history,0),"old incarnation history");long ng=w.BeginSelection(actor).Generation;Check(ng!=g&&w.RetainedCreatureView4FullBytes==0,"reset drains");w.Close();Check(w.RetainedCreatureView4FullBytes==0,"close");}
  foreach(bool acknowledge in new[]{false,true})using(var w=World()){long g=Stage(w,actor,bw);using var r=new SceneWorldCreatureView4FullApplicationRouter(w,e=>{if(acknowledge){var b=w.DrainCreatureView4FullEvents(g)!;w.AcknowledgeCreatureView4FullEvents(b);}else w.AcknowledgeChanges(w.DrainChanges(g)!);return CreatureView4FullCodec.Decode(e,DL);},maximumPayloadBytes:1048576);var s=w.FindCreatureView4Full(g,actor)!;Reject(()=>r.Accept(g,dw));Check(w.IsCurrent(s),"decoder stamp");Reject(()=>r.Accept(g,dw));}
  using(var w=World()){long g=Stage(w,actor,bw);SceneWorldCreatureView4FullApplicationRouter? r=null;r=new(w,e=>{try{r!.Accept(g,dw);}catch(InvalidOperationException){}return CreatureView4FullCodec.Decode(e,DL);},maximumPayloadBytes:1048576);var s=w.FindCreatureView4Full(g,actor)!;Reject(()=>r.Accept(g,dw));Check(w.IsCurrent(s),"swallowed router reentry");r.Dispose();}
  var sc=first.GetProperty("StateCost");long exact=sc.GetProperty("OutputBytes").GetInt64();foreach(long cap in new[]{exact,exact-1})using(var w=World(Policy() with{StoreLimits=Policy().StoreLimits with{MaximumOutputBytes=cap}})){long g=Stage(w,actor,bw);var s=w.FindCreatureView4Full(g,actor)!;if(cap==exact)Check(w.ApplyCreatureView4FullDelta(g,s,dp),"exact aggregate output");else{Reject(()=>w.ApplyCreatureView4FullDelta(g,s,dp));Check(w.IsCurrent(s)&&w.DrainCreatureView4FullEvents(g)!.Events.Count==0,"one-less atomic output");}}
  using(var w=World(full6:new(new(),new(),new(),new()))){var six=Convert.FromHexString(doc.RootElement.GetProperty("Full6Baseline").GetString()!);BinaryPrimitives.WriteUInt64LittleEndian(six.AsSpan(6),actor);long g=Stage(w,actor,bw,six);var before=w.FindCreatureView6Full(g,actor)!;Check(w.Accept(g,dw)&&w.IsCurrent(before)&&w.FindCreatureView4Full(g,actor)is not null,"full6/full4 coexist");}
  File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=checks,Records=records},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R43_CREO4_FULL_WORLD_PASS sequences={records.Count} checks={checks}");
 }
}
